const mouseX = document.querySelector(".mouse_type_x");
const mouseY = document.querySelector(".mouse_type_y");

/*
  Добавьте обработку события onmousemove для объекта document.
  В функции-обработчике при каждом перемещении курсора выводите текущие координаты мыши:
    - значение по оси X — в элементе .mouse_type_x,
    - значение по оси Y — в элементе .mouse_type_y.
*/

document.onmousemove = function (event) {
  mouseX.textContent = event.clientX;
  mouseY.textContent = event.clientY;
};
